/* Подготовка запроса к Ollama для извлечения задачи */
const inputData = $input.first().json;
const body = inputData.body || {};
const query = inputData.query || {};

// Поддержка Telegram-формата и простого {message: "..."}
let message = '';
if (typeof body === 'object' && body !== null) {
  message = (body.message && body.message.text) || body.message || body.text || '';
} else if (typeof body === 'string') {
  message = body;
}
if (!message && query.message) {
  message = query.message;
}
message = String(message).trim();

// Текущая дата/время в UTC+3 (Москва) для разрешения относительных сроков
const now = new Date();
const tzOffset = 3; // Europe/Moscow = UTC+3
const localTime = new Date(now.getTime() + tzOffset * 3600000);
const currentDateStr = localTime.toISOString().replace('T', ' ').slice(0, 19);

const systemPrompt = [
  'Ты — ИИ-агент-ассистент. Анализируй поручения пользователя и извлекай структурированные данные для создания задачи в календаре.',
  '',
  'Текущая дата и время (UTC+3, Europe/Moscow): ' + currentDateStr,
  '',
  'Из входящего сообщения извлеки следующие поля:',
  '1. task_name — краткое и понятное название задачи (что нужно сделать)',
  '2. deadline — срок выполнения в формате ISO 8601 (YYYY-MM-DDTHH:MM:SS), время в часовом поясе UTC+3',
  '3. duration_minutes — предполагаемая длительность в минутах (по умолчанию 60)',
  '4. description — краткое описание или контекст задачи',
  '5. priority — приоритет: high, medium или low (по умолчанию medium)',
  '',
  'Правила определения срока:',
  '- "завтра утром" → завтра 09:00',
  '- "завтра днем" → завтра 13:00',
  '- "завтра вечером" → завтра 18:00',
  '- "к пятнице" → ближайшая пятница 18:00',
  '- "к пятнице до 15:00" → ближайшая пятница 15:00',
  '- "до 15:00" → сегодня 15:00 (если уже позже — завтра 15:00)',
  '- "через 3 дня" → текущая дата + 3 дня 09:00',
  '- "на следующей неделе" → понедельник следующей недели 09:00',
  '- если срок не указан → завтра 09:00',
  '',
  'Верни ТОЛЬКО валидный JSON (без markdown, без кодовых блоков, без пояснений):',
  '{"task_name":"...","deadline":"YYYY-MM-DDTHH:MM:SS","duration_minutes":60,"description":"...","priority":"medium"}'
].join('\n');

const requestBody = {
  model: 'glm-5.2:cloud',
  stream: false,
  format: 'json',
  messages: [
    { role: 'system', content: systemPrompt },
    { role: 'user', content: message }
  ]
};

return [{ json: { requestBody, originalMessage: message } }];

/* Парсинг ответа LLM и построение iCalendar-события */
const input = $input.first().json;
const rawContent = input.message?.content ?? input.content ?? '';
const originalMessage = $('Prepare LLM Request').first().json.originalMessage || '';

// Парсим JSON из ответа LLM (с обработкой markdown-обёрток)
let text = String(rawContent).trim();
text = text.replace(/^```(?:json)?\s*/i, '').replace(/\s*```$/i, '').trim();

let parsed = {};
try {
  parsed = JSON.parse(text);
} catch (e) {
  const match = text.match(/\{[\s\S]*\}/);
  if (match) {
    try { parsed = JSON.parse(match[0]); } catch (e2) { parsed = {}; }
  }
}

// Извлекаем поля
const taskName = String(parsed.task_name || 'Задача без названия');
const description = String(parsed.description || originalMessage);
const priority = String(parsed.priority || 'medium');
const durationMinutes = parseInt(parsed.duration_minutes) || 60;

// Парсим дедлайн
let deadline;
try {
  deadline = parsed.deadline ? new Date(parsed.deadline) : new Date(Date.now() + 86400000);
  if (isNaN(deadline.getTime())) {
    deadline = new Date(Date.now() + 86400000);
  }
} catch (e) {
  deadline = new Date(Date.now() + 86400000);
}

// Конвертация в iCalendar UTC формат: YYYYMMDDTHHMMSSZ
function toICAL(date) {
  return date.getUTCFullYear().toString() +
    String(date.getUTCMonth() + 1).padStart(2, '0') +
    String(date.getUTCDate()).padStart(2, '0') + 'T' +
    String(date.getUTCHours()).padStart(2, '0') +
    String(date.getUTCMinutes()).padStart(2, '0') +
    String(date.getUTCSeconds()).padStart(2, '0') + 'Z';
}

const dtStart = toICAL(deadline);
const endDate = new Date(deadline.getTime() + durationMinutes * 60000);
const dtEnd = toICAL(endDate);
const dtStamp = toICAL(new Date());

// Генерируем UID события
const uuid = Date.now().toString(36) + '-' + Math.random().toString(36).slice(2, 10) + '@n8n-agent';

// Приоритет iCalendar (1=высокий, 5=средний, 9=низкий)
const icalPriority = priority === 'high' ? 1 : priority === 'low' ? 9 : 5;

// Очистка текста для iCalendar
function cleanICAL(text) {
  return String(text).replace(/[\n;,\\]/g, ' ').trim();
}

// Строим iCalendar-тело (CRLF — стандарт iCalendar)
const icalBody = [
  'BEGIN:VCALENDAR',
  'VERSION:2.0',
  'PRODID:-//n8n AI Agent//RU',
  'CALSCALE:GREGORIAN',
  'BEGIN:VEVENT',
  'UID:' + uuid,
  'DTSTAMP:' + dtStamp,
  'DTSTART:' + dtStart,
  'DTEND:' + dtEnd,
  'SUMMARY:' + cleanICAL(taskName),
  'DESCRIPTION:' + cleanICAL(description),
  'PRIORITY:' + icalPriority,
  'END:VEVENT',
  'END:VCALENDAR'
].join('\r\n') + '\r\n';

// Данные для Yandex Calendar (CalDAV)
const yandexEmail = 'web-nnru@yandex.ru';
const yandexPassword = 'mzffbcryjqytxefz';
const calendarId = 'events-4135431';

const caldavUrl = 'https://caldav.yandex.ru/calendars/' + encodeURIComponent(yandexEmail) + '/' + calendarId + '/' + uuid + '.ics';
const authHeader = 'Basic ' + Buffer.from(yandexEmail + ':' + yandexPassword).toString('base64');

return [{
  json: {
    original_message: originalMessage,
    task_name: taskName,
    deadline: parsed.deadline || deadline.toISOString(),
    deadline_ical: dtStart,
    duration_minutes: durationMinutes,
    description: description,
    priority: priority,
    event_uid: uuid,
    ical_body: icalBody,
    caldav_url: caldavUrl,
    auth_header: authHeader,
    status: 'parsed'
  }
}];

/* Создание события в Yandex Calendar через CalDAV PUT */
const eventData = $input.first().json;

const options = {
  method: 'PUT',
  url: eventData.caldav_url,
  headers: {
    'Content-Type': 'text/calendar; charset=utf-8',
    'Authorization': eventData.auth_header
  },
  body: eventData.ical_body,
  encoding: 'utf8',
  skipSslCertificateVerification: true,
  returnFullResponse: true,
  timeout: 30000
};

let statusCode = 0;
let responseBody = '';
let errorMessage = '';

try {
  const response = await this.helpers.httpRequest(options);
  // httpRequest with returnFullResponse returns { statusCode, body, headers }
  if (response && typeof response.statusCode === 'number') {
    statusCode = response.statusCode;
    responseBody = typeof response.body === 'string' ? response.body : JSON.stringify(response.body);
  } else {
    // Если вернулся 直接 body (не full response)
    statusCode = 200;
    responseBody = String(response);
  }
} catch (err) {
  // Ошибка может содержать statusCode
  statusCode = err.statusCode || 0;
  responseBody = err.message || String(err);
  errorMessage = err.message || String(err);
}

return [{
  json: {
    statusCode: statusCode,
    body: responseBody,
    error: errorMessage,
    caldav_url: eventData.caldav_url,
    event_uid: eventData.event_uid,
    status: (statusCode === 201 || statusCode === 204) ? 'created' : 'failed'
  }
}];

/* Подготовка ответа пользователю */
const eventData = $('Parse and Build Event').first().json;
const calResult = $input.first();

let calStatus = 'created';
let calError = '';
let calHttpCode = null;

if (calResult && calResult.json) {
  calHttpCode = calResult.json.statusCode || calResult.json.status || null;
  if (calResult.json.error || (calHttpCode && calHttpCode >= 400)) {
    calStatus = 'failed';
    calError = String((calResult.json.error && calResult.json.error.message) || calResult.json.error || ('HTTP ' + calHttpCode));
  }
}

const task = {
  name: eventData.task_name,
  deadline: eventData.deadline,
  description: eventData.description,
  priority: eventData.priority,
  duration_minutes: eventData.duration_minutes
};

const calLine = calStatus === 'created'
  ? '✅ Событие создано в Яндекс.Календаре'
  : '⚠️ Событие в календаре не создано: ' + calError;

const confirmation = [
  '✅ Задача принята!',
  '',
  '📋 ' + task.name,
  '📅 Срок: ' + task.deadline,
  '⏱ Длительность: ' + task.duration_minutes + ' мин',
  '📊 Приоритет: ' + task.priority,
  '',
  calLine
].join('\n');

return [{
  json: {
    status: 'success',
    confirmation: confirmation,
    task: task,
    calendar_event: {
      status: calStatus,
      uid: eventData.event_uid,
      http_code: calHttpCode,
      error: calError
    },
    timestamp: new Date().toISOString()
  }
}];
